<?php
namespace Tests\Feature;
use App\Models\Cliente; use App\Models\Contrato; use App\Models\Movimiento; use App\Models\Propiedad; use App\Models\User; use App\Services\AutomaticContractChargeService; use App\Services\ReporteFinancieroService;
use Illuminate\Database\QueryException;
use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Schema; use Tests\TestCase;
class AutomaticContractChargesTest extends TestCase {
 use RefreshDatabase;
 private function fixture(float $percent=10, float $initial=0): array { $c=Cliente::create(['nombre'=>'C','rfc'=>'XAXX010101000','domicilio'=>'D']); $p=Propiedad::create(['fk_cliente'=>$c->pk_cliente,'alias'=>'P'.uniqid()]); $contract=Contrato::create(['fk_cliente'=>$c->pk_cliente,'fk_propiedad'=>$p->pk_propiedad,'fecha'=>now(),'fecha_inicio'=>now()->startOfMonth(),'fecha_fin'=>now()->endOfMonth(),'comision_mensual'=>$percent,'comision_renta'=>$initial,'origen'=>'privado']); return [$c,$p,$contract]; }
 private function rent(Propiedad $p, Cliente $c, float $amount, string $status='approved', string $payment='efectivo'): Movimiento { return Movimiento::create(['cliente_id'=>$c->pk_cliente,'propiedad_id'=>$p->pk_propiedad,'asignado_a_tipo'=>'propiedad','concepto'=>'renta','fecha'=>now(),'importe'=>$amount,'forma_pago'=>$payment,'approval_status'=>$status,'estado_pago'=>$status==='approved'?'liquidado':'pendiente','afecta_saldo_cliente'=>true]); }
 public function test_monthly_commission_is_per_rent_idempotent_and_recalculates(): void { [$c,$p]=$this->fixture(); $r=$this->rent($p,$c,10000); $s=app(AutomaticContractChargeService::class); $s->reconcileMonthlyCommission($r); $s->reconcileMonthlyCommission($r); $this->assertDatabaseCount('movimientos',2); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$r->id,'importe'=>1000,'automation_type'=>'monthly_commission','auto_generated'=>1,'afecta_saldo_cliente'=>1]); $r->update(['importe'=>4000]); $s->reconcileMonthlyCommission($r); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$r->id,'importe'=>400]); }
 public function test_partial_transfer_and_distinct_rents_create_independent_commissions(): void { [$c,$p]=$this->fixture(); $s=app(AutomaticContractChargeService::class); $cash=$this->rent($p,$c,5000); $transfer=$this->rent($p,$c,5000,'approved','transferencia'); $s->reconcileMonthlyCommission($cash); $s->reconcileMonthlyCommission($transfer); $this->assertSame(2,Movimiento::where('automation_type','monthly_commission')->count()); $this->assertSame(1000.0,(float)Movimiento::where('automation_type','monthly_commission')->sum('importe')); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$transfer->id,'importe'=>500,'afecta_saldo_cliente'=>1]); }
 public function test_pending_source_non_rent_removal_recreation_and_manual_iguala_are_safe(): void { [$c,$p]=$this->fixture(); $r=$this->rent($p,$c,1000,'pending'); $s=app(AutomaticContractChargeService::class); $s->reconcileMonthlyCommission($r); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$r->id,'approval_status'=>'pending']); Movimiento::create(['cliente_id'=>$c->pk_cliente,'propiedad_id'=>$p->pk_propiedad,'asignado_a_tipo'=>'propiedad','concepto'=>'iguala','fecha'=>now(),'importe'=>99,'forma_pago'=>'efectivo','approval_status'=>'approved','estado_pago'=>'liquidado','auto_generated'=>false]); $r->update(['concepto'=>'gasto']); $s->reconcileMonthlyCommission($r); $this->assertDatabaseMissing('movimientos',['source_movimiento_id'=>$r->id]); $this->assertDatabaseHas('movimientos',['importe'=>99,'auto_generated'=>0]); $r->update(['concepto'=>'renta']); $s->reconcileMonthlyCommission($r); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$r->id,'importe'=>100]); }
 public function test_initial_commission_is_once_per_contract_and_skips_non_positive_values(): void { [$c,$p,$contract]=$this->fixture(10,1200); $s=app(AutomaticContractChargeService::class); $s->ensureInitialCommission($contract); $s->ensureInitialCommission($contract); $charge=Movimiento::where('contrato_id',$contract->id)->where('automation_type','initial_commission')->sole(); $this->assertSame(1200.0,(float) $charge->importe); $this->assertSame($contract->fecha_inicio->toDateString(), $charge->fecha->toDateString()); $this->assertTrue($charge->afecta_saldo_cliente); $this->assertSame(1,Movimiento::where('automation_type','initial_commission')->count()); [,,$zero]=$this->fixture(10,0); $s->ensureInitialCommission($zero); [,,$negative]=$this->fixture(10,-1); $s->ensureInitialCommission($negative); [,,$null]=$this->fixture(10,1); $null->update(['comision_renta'=>null]); $s->ensureInitialCommission($null); $this->assertSame(1,Movimiento::where('automation_type','initial_commission')->count()); }
 public function test_changing_the_rent_period_reuses_its_charge_and_recalculates_for_the_new_contract(): void { [$c,$p,$first]=$this->fixture(10); $nextMonth=now()->addMonthNoOverflow()->startOfMonth(); $second=Contrato::create(['fk_cliente'=>$c->pk_cliente,'fk_propiedad'=>$p->pk_propiedad,'fecha'=>now(),'fecha_inicio'=>$nextMonth,'fecha_fin'=>$nextMonth->copy()->endOfMonth(),'comision_mensual'=>5,'origen'=>'privado']); $rent=$this->rent($p,$c,10000); $s=app(AutomaticContractChargeService::class); $s->reconcileMonthlyCommission($rent); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$rent->id,'contrato_id'=>$first->id,'importe'=>1000]); $rent->update(['fecha'=>$nextMonth]); $s->reconcileMonthlyCommission($rent); $charge=Movimiento::where('source_movimiento_id',$rent->id)->sole(); $this->assertSame($second->id,$charge->contrato_id); $this->assertSame(500.0,(float)$charge->importe); $this->assertSame(1,Movimiento::where('source_movimiento_id',$rent->id)->count()); }
 public function test_individual_and_bulk_approval_sync_the_generated_commission(): void { [$c,$p]=$this->fixture(); $service=app(AutomaticContractChargeService::class); $first=$this->rent($p,$c,1000,'pending'); $second=$this->rent($p,$c,2000,'pending'); $service->reconcileMonthlyCommission($first); $service->reconcileMonthlyCommission($second); $admin=User::factory()->create(['role'=>User::ROLE_ADMIN]); $this->actingAs($admin)->patch(route('movimientos.approve',$first))->assertRedirect(route('movimientos.index')); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$first->id,'approval_status'=>'approved']); $this->actingAs($admin)->patch(route('movimientos.approve-bulk'),['movimientos'=>[$second->id]])->assertRedirect(route('movimientos.index')); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$second->id,'approval_status'=>'approved']); }
 public function test_controller_destroy_removes_only_its_automatic_commission(): void { [$c,$p]=$this->fixture(); $rent=$this->rent($p,$c,1000); $service=app(AutomaticContractChargeService::class); $service->reconcileMonthlyCommission($rent); $manual=Movimiento::create(['cliente_id'=>$c->pk_cliente,'propiedad_id'=>$p->pk_propiedad,'asignado_a_tipo'=>'propiedad','concepto'=>'iguala','fecha'=>now(),'importe'=>22,'forma_pago'=>'efectivo','approval_status'=>'approved','estado_pago'=>'liquidado','auto_generated'=>false]); $admin=User::factory()->create(['role'=>User::ROLE_ADMIN]); $this->actingAs($admin)->delete(route('movimientos.destroy',$rent))->assertRedirect(route('movimientos.index')); $this->assertDatabaseMissing('movimientos',['id'=>$rent->id]); $this->assertDatabaseMissing('movimientos',['source_movimiento_id'=>$rent->id]); $this->assertDatabaseHas('movimientos',['id'=>$manual->id,'auto_generated'=>0]); }
 public function test_unique_source_reference_is_structural(): void { [$c,$p]=$this->fixture(); $rent=$this->rent($p,$c,1000); $service=app(AutomaticContractChargeService::class); $service->reconcileMonthlyCommission($rent); $this->expectException(QueryException::class); Movimiento::create(['cliente_id'=>$c->pk_cliente,'propiedad_id'=>$p->pk_propiedad,'asignado_a_tipo'=>'propiedad','concepto'=>'iguala','fecha'=>now(),'importe'=>1,'forma_pago'=>'efectivo','source_movimiento_id'=>$rent->id,'auto_generated'=>true]); }
 public function test_automation_migration_columns_are_available_for_legacy_rows(): void { $this->assertTrue(Schema::hasColumns('movimientos',['source_movimiento_id','contrato_id','automation_type','auto_generated'])); $legacy=Movimiento::create(['asignado_a_tipo'=>'cliente','cliente_id'=>$this->fixture()[0]->pk_cliente,'concepto'=>'gasto','fecha'=>now(),'importe'=>1,'forma_pago'=>'efectivo'])->fresh(); $this->assertNull($legacy->source_movimiento_id); $this->assertNull($legacy->contrato_id); $this->assertNull($legacy->automation_type); $this->assertFalse($legacy->auto_generated); }
 public function test_automation_foreign_keys_null_their_links_when_a_source_or_contract_is_removed(): void { [$c,$p,$contract]=$this->fixture(10,100); $rent=$this->rent($p,$c,1000); $service=app(AutomaticContractChargeService::class); $service->reconcileMonthlyCommission($rent); $monthly=Movimiento::where('source_movimiento_id',$rent->id)->sole(); $service->ensureInitialCommission($contract); $initial=Movimiento::where('contrato_id',$contract->id)->where('automation_type','initial_commission')->sole(); $rent->delete(); $contract->delete(); $this->assertNull($monthly->fresh()->source_movimiento_id); $this->assertNull($monthly->fresh()->contrato_id); $this->assertNull($initial->fresh()->contrato_id); }
 public function test_agent_update_returns_rent_and_charge_to_pending_while_admin_update_keeps_them_approved(): void { [$c,$p]=$this->fixture(); $rent=$this->rent($p,$c,1000); $service=app(AutomaticContractChargeService::class); $service->reconcileMonthlyCommission($rent); $payload=['asignado_a_tipo'=>'propiedad','propiedad_id'=>$p->pk_propiedad,'concepto'=>'renta','fecha'=>now()->toDateString(),'importe'=>'900.00','forma_pago'=>'efectivo','estado_pago'=>'liquidado','fecha_liquidacion'=>now()->toDateString(),'afecta_saldo_cliente'=>'1']; $agent=User::factory()->create(['role'=>User::ROLE_AGENT]); $this->actingAs($agent)->put(route('movimientos.update',$rent),$payload)->assertRedirect(route('movimientos.index')); $this->assertDatabaseHas('movimientos',['id'=>$rent->id,'approval_status'=>'pending']); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$rent->id,'approval_status'=>'pending','importe'=>90]); $admin=User::factory()->create(['role'=>User::ROLE_ADMIN]); $this->actingAs($admin)->put(route('movimientos.update',$rent),array_replace($payload,['importe'=>'800.00']))->assertRedirect(route('movimientos.index')); $this->assertDatabaseHas('movimientos',['id'=>$rent->id,'approval_status'=>'approved']); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$rent->id,'approval_status'=>'approved','importe'=>80]); }
 public function test_controller_store_creates_the_rent_and_its_charge_together(): void { [$c,$p]=$this->fixture(); $admin=User::factory()->create(['role'=>User::ROLE_ADMIN]); $this->actingAs($admin)->post(route('movimientos.store'),['asignado_a_tipo'=>'propiedad','propiedad_id'=>$p->pk_propiedad,'concepto'=>'renta','fecha'=>now()->toDateString(),'importe'=>'10000.00','forma_pago'=>'efectivo','estado_pago'=>'liquidado','fecha_liquidacion'=>now()->toDateString(),'afecta_saldo_cliente'=>'1'])->assertRedirect(route('movimientos.index')); $rent=Movimiento::where('concepto','renta')->sole(); $this->assertDatabaseHas('movimientos',['source_movimiento_id'=>$rent->id,'automation_type'=>'monthly_commission','importe'=>1000,'approval_status'=>'approved']); }
 public function test_real_automatic_charges_are_classified_in_financial_reports_and_available_balance(): void { [$c,$p,$contract]=$this->fixture(10,12000); $service=app(AutomaticContractChargeService::class); $cash=$this->rent($p,$c,10000); $transfer=$this->rent($p,$c,10000,'approved','transferencia'); $service->reconcileMonthlyCommission($cash); $service->reconcileMonthlyCommission($transfer); $service->ensureInitialCommission($contract); $report=app(ReporteFinancieroService::class)->generarPorCliente($c->pk_cliente,now()->startOfMonth(),now()->endOfMonth()); $this->assertSame(14000.0,$report['periodo']['igualas']); $this->assertSame(10000.0,$report['periodo']['transferencias_informativas']); $this->assertSame(-4000.0,$report['saldo_final']); $this->assertSame(-4000.0,app(ReporteFinancieroService::class)->saldosDisponiblesPorCliente([$c->pk_cliente])[$c->pk_cliente]); }
 public function test_available_balance_uses_only_settled_financial_funds_and_matches_the_report(): void { [$c,$p,$contract]=$this->fixture(10,500); app(AutomaticContractChargeService::class)->ensureInitialCommission($contract); $pending=$this->rent($p,$c,10000); $pending->update(['estado_pago'=>'pendiente','fecha_liquidacion'=>null]); $transfer=$this->rent($p,$c,3000,'approved','transferencia'); Movimiento::create(['cliente_id'=>$c->pk_cliente,'propiedad_id'=>$p->pk_propiedad,'asignado_a_tipo'=>'propiedad','concepto'=>'iguala','fecha'=>now(),'importe'=>1000,'forma_pago'=>'efectivo','approval_status'=>'approved','estado_pago'=>'liquidado','afecta_saldo_cliente'=>true,'auto_generated'=>true,'automation_type'=>'monthly_commission']); Movimiento::create(['cliente_id'=>$c->pk_cliente,'propiedad_id'=>$p->pk_propiedad,'asignado_a_tipo'=>'propiedad','concepto'=>'pago_cliente','fecha'=>now(),'importe'=>200,'forma_pago'=>'efectivo','approval_status'=>'approved','estado_pago'=>'liquidado','afecta_saldo_cliente'=>true]); Movimiento::create(['cliente_id'=>$c->pk_cliente,'propiedad_id'=>$p->pk_propiedad,'asignado_a_tipo'=>'propiedad','concepto'=>'gasto','fecha'=>now(),'importe'=>999,'forma_pago'=>'efectivo','approval_status'=>'approved','estado_pago'=>'cancelado','afecta_saldo_cliente'=>true]); $financial=app(ReporteFinancieroService::class); $this->assertSame(-1700.0,$financial->saldosDisponiblesPorCliente([$c->pk_cliente])[$c->pk_cliente]); $pending->update(['estado_pago'=>'liquidado','fecha_liquidacion'=>now()]); $this->assertSame(8300.0,$financial->saldosDisponiblesPorCliente([$c->pk_cliente])[$c->pk_cliente]); $report=$financial->generarPorCliente($c->pk_cliente,now()->startOfMonth(),now()->endOfMonth()); $this->assertSame($report['saldo_disponible_para_pago'],$financial->saldosDisponiblesPorCliente([$c->pk_cliente])[$c->pk_cliente]); }
}
